#include <omp.h>
#include <array>
#include <cstddef>
#include <vector>

using std::size_t;

void countQuadrants(std::vector<Point> const& points, std::array<size_t, 4> &bins) {
    size_t q1 = 0; // x > 0, y > 0
    size_t q2 = 0; // x < 0, y > 0
    size_t q3 = 0; // x < 0, y < 0
    size_t q4 = 0; // x > 0, y < 0

    const size_t n = points.size();

    #pragma omp parallel for default(none) shared(points, n) reduction(+:q1, q2, q3, q4)
    for (size_t i = 0; i < n; ++i) {
        const Point& p = points[i];

        // Points on either axis are not in any quadrant.
        if (p.x > 0.0) {
            if (p.y > 0.0) {
                ++q1;
            } else if (p.y < 0.0) {
                ++q4;
            }
        } else if (p.x < 0.0) {
            if (p.y > 0.0) {
                ++q2;
            } else if (p.y < 0.0) {
                ++q3;
            }
        }
    }

    bins[0] = q1;
    bins[1] = q2;
    bins[2] = q3;
    bins[3] = q4;
}
